import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_UPDATED_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_EXT_MARKERS = ("ext", "x", "#")


def _text(value):
    return "" if value is None else str(value)


def _normalize_email(raw):
    s = _text(raw)
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            domain = "gmail.com"
        s = local + "@" + domain
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _normalize_phone(raw):
    s = _text(raw).lower()
    cuts = [s.find(marker) for marker in _EXT_MARKERS]
    cuts = [i for i in cuts if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(ch for ch in s if "0" <= ch <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = _text(raw).strip()
    if re.fullmatch(r"[0-9]{5}-[0-9]{4}", s):
        s = s.split("-", 1)[0]
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _normalize_name(raw):
    s = _text(raw).strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = _text(raw).strip()
    for fmt in _UPDATED_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _opted_out(raw):
    return _text(raw).strip().lower() in _OPT_OUT_VALUES


def _normalize_tags(raw):
    parts = re.split(r"[;,]", _text(raw))
    return {p.strip().lower() for p in parts if p.strip()}


def _merge_group(recs, members):
    def pick(field):
        cands = [m for m in members if recs[m][field]]
        if not cands:
            return ""
        # Stable multi-pass sort: input order, then most recent updated,
        # then manual-source rows first.
        order = sorted(cands)
        order.sort(key=lambda m: recs[m]["updated"] or datetime.min, reverse=True)
        order.sort(key=lambda m: not recs[m]["manual"])
        return recs[order[0]][field]

    tags = set()
    for m in members:
        tags |= recs[m]["tags"]

    updated_vals = [recs[m]["updated"] for m in members if recs[m]["updated"] is not None]
    latest = max(updated_vals).strftime("%Y-%m-%d") if updated_vals else ""

    return {
        "first_name": pick("first_name"),
        "last_name": pick("last_name"),
        "zip": pick("zip"),
        "email": pick("email"),
        "phone": pick("phone"),
        "source": pick("source"),
        "tags": ";".join(sorted(tags)),
        "opted_out": "Y" if any(recs[m]["opted_out"] for m in members) else "N",
        "updated": latest,
    }


def dedupe_contacts(rows):
    # Normalize each row and drop rows with neither a valid email nor a valid phone.
    recs = []
    for row in rows:
        email = _normalize_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not (email_ok or phone_ok):
            continue
        source = _text(row.get("source")).strip().lower()
        recs.append({
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": source,
            "manual": source == "manual",
            "tags": _normalize_tags(row.get("tags")),
            "opted_out": _opted_out(row.get("opted_out")),
            "updated": _parse_updated(row.get("updated")),
        })

    # Union-find so matching is transitive.
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for i, rec in enumerate(recs):
        if rec["email"]:
            if rec["email"] in first_by_email:
                union(first_by_email[rec["email"]], i)
            else:
                first_by_email[rec["email"]] = i
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Group rows; dict order follows each group's earliest input row.
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    return [_merge_group(recs, members) for members in groups.values()]
